import {$,esc,subjectStats,studentSubjectRows,lectureStats,toast} from './ui.js';import {exportTableExcel,exportTablePdf,exportTableCsv} from './export-utils.js';
let data,type='semester',subject='',student='',section='',from='',to='',lecture='';
export async function render(d){data=d;draw()}
function draw(){$('#page').innerHTML=`<div class="page-heading"><div><h1>Export Data</h1><p>Prepare clean attendance files for submission or review.</p></div></div><div class="card toolbar"><div class="field grow"><label>Export Scope</label><select class="select" id="type"><option value="semester" ${type==='semester'?'selected':''}>Entire Semester</option><option value="lecture" ${type==='lecture'?'selected':''}>Single Lecture</option><option value="student" ${type==='student'?'selected':''}>Student</option><option value="subject" ${type==='subject'?'selected':''}>Subject</option><option value="date" ${type==='date'?'selected':''}>Date Range</option><option value="section" ${type==='section'?'selected':''}>Section</option><option value="short" ${type==='short'?'selected':''}>Students Below ${data.settings?.minimum_attendance||75}%</option></select></div>${type==='lecture'?`<div class="field grow"><label>Lecture</label><select class="select" id="lecture">${data.lectures.sort((a,b)=>b.lecture_date.localeCompare(a.lecture_date)).map(l=>{const s=data.subjects.find(x=>x.id===l.subject_id)||{};return`<option value="${l.id}" ${lecture===l.id?'selected':''}>${esc(s.subject_code)} · Lecture ${l.lecture_number} · ${l.lecture_date}</option>`}).join('')}</select></div>`:''}${type==='student'?selectStudent():''}${type==='subject'?selectSubject():''}${type==='section'?selectSection():''}${type==='date'?`<div class="field"><label>From</label><input class="input" id="from" type="date" value="${from}"></div><div class="field"><label>To</label><input class="input" id="to" type="date" value="${to}"></div>`:''}</div><div class="export-grid"><article class="card export-card"><span class="export-icon excel"><i class="bi bi-file-earmark-spreadsheet-fill"></i></span><h2>Export Excel</h2><p>Download a structured .xlsx workbook ready for filtering and further analysis.</p><button class="btn btn-primary" data-format="xlsx"><i class="bi bi-download"></i> Download Excel</button></article><article class="card export-card"><span class="export-icon pdf"><i class="bi bi-file-earmark-pdf-fill"></i></span><h2>Export PDF</h2><p>Create a professional, printable report with a clear generated date.</p><button class="btn btn-primary" data-format="pdf"><i class="bi bi-download"></i> Download PDF</button></article><article class="card export-card"><span class="export-icon csv"><i class="bi bi-filetype-csv"></i></span><h2>Export CSV</h2><p>Get a lightweight, universal data file for spreadsheets and other systems.</p><button class="btn btn-primary" data-format="csv"><i class="bi bi-download"></i> Download CSV</button></article></div><p class="footer-note"><i class="bi bi-shield-check"></i> Exports include only the records selected above.</p>`;bind()}
function selectStudent(){return`<div class="field grow"><label>Student</label><select class="select" id="student">${data.students.map(s=>`<option value="${s.id}" ${student===s.id?'selected':''}>${esc(s.roll_no)} · ${esc(s.name)}</option>`).join('')}</select></div>`}function selectSubject(){return`<div class="field grow"><label>Subject</label><select class="select" id="subject">${data.subjects.map(s=>`<option value="${s.id}" ${subject===s.id?'selected':''}>${esc(s.subject_name)}</option>`).join('')}</select></div>`}function selectSection(){return`<div class="field"><label>Section</label><select class="select" id="section">${[...new Set(data.students.map(s=>s.section))].map(x=>`<option ${section===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div>`}
function getRows(){const threshold=Number(data.settings?.minimum_attendance||75);if(type==='short')return studentSubjectRows(data).filter(x=>x.percentage<threshold).map(x=>({'Roll No':x.student.roll_no,'Student Name':x.student.name,Subject:x.subject.subject_name,Present:x.present,'Total Lectures':x.total,'Attendance %':x.percentage}));let lectures=data.lectures;if(type==='lecture')lectures=lectures.filter(l=>l.id===(lecture||data.lectures[0]?.id));if(type==='subject')lectures=lectures.filter(l=>l.subject_id===(subject||data.subjects[0]?.id));if(type==='date')lectures=lectures.filter(l=>(!from||l.lecture_date>=from)&&(!to||l.lecture_date<=to));if(type==='section')lectures=lectures.filter(l=>l.section===(section||data.students[0]?.section));const lids=lectures.map(l=>l.id),selectedStudent=student||data.students[0]?.id;return data.attendance.filter(a=>lids.includes(a.lecture_id)&&(type!=='student'||a.student_id===selectedStudent)).map(a=>{const l=data.lectures.find(x=>x.id===a.lecture_id)||{},s=data.students.find(x=>x.id===a.student_id)||{},sub=data.subjects.find(x=>x.id===l.subject_id)||{};return{Date:l.lecture_date,Subject:sub.subject_name,'Lecture Number':l.lecture_number,'Roll Number':s.roll_no,'Student Name':s.name,Section:l.section,Status:a.status==='present'?'Present':'Absent'}})}
function bind(){$('#type').onchange=e=>{type=e.target.value;draw()};const ids=['lecture','student','subject','section','from','to'];ids.forEach(id=>{const el=$(`#${id}`);if(el)el.onchange=e=>{({lecture:v=>lecture=v,student:v=>student=v,subject:v=>subject=v,section:v=>section=v,from:v=>from=v,to:v=>to=v}[id])(e.target.value)}});document.querySelectorAll('[data-format]').forEach(b=>b.onclick=()=>{const rows=getRows();if(!rows.length){toast('No records match this export scope.','error');return}const name=`attendance-${type}-report`;if(b.dataset.format==='xlsx')exportTableExcel(name,rows);if(b.dataset.format==='pdf')exportTablePdf('Class Attendance Report',rows);if(b.dataset.format==='csv')exportTableCsv(name,rows)})}
